import re

def parse_kv(s):
    if not s:
        return {}

    result = {}

    # Use regex to split by semicolon only if it is not escaped (not preceded by a backslash)
    # and ensure the semicolon is not the very last character if it's an unescaped trailing separator
    # This regex looks for an unescaped semicolon: (?<!\\);
    pairs = re.split(r'(?<!\\);', s)

    for pair in pairs:
        pair = pair.strip()
        if not pair:
            continue

        # Find the first '='
        if '=' not in pair:
            continue

        key, value = pair.split('=', 1)

        # Trim key and value
        key = key.strip()
        value = value.strip()

        # Handle escaped semicolons (\;) in the value by replacing them with literal ;
        # Note: we only handle escaping related to semicolons as per requirements.
        value = value.replace('\\;', ';')

        if key:
            result[key] = value

    return result

