import pytest
from parse_kv import parse_kv

def test_empty_string():
    assert parse_kv("") == {}

def test_basic_parsing():
    assert parse_kv("key1=value1; key2=value2") == {'key1': 'value1', 'key2': 'value2'}

def test_whitespace_trimming():
    assert parse_kv(" key1 = value1 ; key2 = value2 ") == {'key1': 'value1', 'key2': 'value2'}

def test_key_only():
    # If there is a key but no value after '=', it should handle it (empty string value)
    # If no '=' is present, the pair should be ignored/skipped.
    assert parse_kv("key1=; key2") == {'key1': ''}

def test_escaped_semicolon_in_value():
    # A backslash-escaped semicolon \; should be treated as a literal semicolon
    input_str = "key1=value1 with \; ; key2=value2"
    expected = {'key1': 'value1 with ;', 'key2': 'value2'}
    assert parse_kv(input_str) == expected

def test_complex_values():
    input_str = "k1=v1; k2=v2 with a semicolon ; k3=v3; k4=complex value"
    expected = {'k1': 'v1', 'k2': 'v2 with a semicolon', 'k3': 'v3', 'k4': 'complex value'}
    assert parse_kv(input_str) == expected

def test_leading_and_trailing_whitespace():
    assert parse_kv("  key1=value1; key2=value2  ") == {'key1': 'value1', 'key2': 'value2'}

